//! Languages served by `GET /detect/languages`, compiled from `data/languages.json`.

use serde::{Deserialize, Serialize};
use utoipa::ToSchema;

use crate::detect::Method;

/// Response body of `GET /detect/languages`, generated by `build.rs`.
pub(crate) const JSON: &str = include_str!(concat!(env!("OUT_DIR"), "/languages.json"));

/// A language and the methods that can detect it.
#[derive(Debug, Deserialize, Serialize, ToSchema)]
pub(crate) struct Language {
    /// ISO 639-1 code.
    #[schema(example = "en")]
    pub(crate) iso_639_1: String,
    /// English name.
    #[schema(example = "English")]
    pub(crate) name: String,
    /// Methods that can return this language.
    pub(crate) methods: Vec<Method>,
}

#[cfg(test)]
mod tests {
    use std::collections::BTreeSet;

    use super::*;

    fn languages() -> Vec<Language> {
        serde_json::from_str(JSON).unwrap()
    }

    fn codes(method: Method) -> BTreeSet<String> {
        languages()
            .into_iter()
            .filter(|l| l.methods.contains(&method))
            .map(|l| l.iso_639_1)
            .collect()
    }

    /// ISO 639-1 code of a MediaPipe label, as mapped by the Python service's language list.
    fn iso_639_1(label: &str) -> Option<&str> {
        match label.split('-').next()? {
            "unknown" => None,
            "iw" => Some("he"),
            "fil" => Some("tl"),
            code => Some(code),
        }
    }

    #[test]
    fn list_is_sorted_by_code() {
        let languages = languages();
        assert!(languages.windows(2).all(|w| w[0].iso_639_1 < w[1].iso_639_1));
    }

    #[test]
    fn mediapipe_languages_match_the_model() {
        let detector = langer_mediapipe::Detector::new();
        let model: BTreeSet<String> = detector.labels().filter_map(iso_639_1).map(str::to_owned).collect();
        assert_eq!(codes(Method::Mediapipe), model, "update data/languages.json");
    }

    #[test]
    fn lingua_languages_match_the_lingua_crate() {
        let expected: BTreeSet<String> = lingua::Language::all()
            .iter()
            .map(|l| l.iso_code_639_1().to_string())
            .collect();
        assert_eq!(codes(Method::Lingua), expected, "update data/languages.json");
    }
}
